import{_ as e,o,c as r,a2 as t}from"./chunks/framework.BjkiRu3Q.js";const s="/images/cliente/checkout-pasos.webp",n="/images/cliente/checkout-pago.webp",g=JSON.parse('{"title":"6. Cómo Pagar tu Compra (Paso a Paso)","description":"","frontmatter":{},"headers":[],"relativePath":"cliente/checkout.md","filePath":"cliente/checkout.md"}'),i={name:"cliente/checkout.md"};function c(l,a,d,p,u,m){return o(),r("div",null,[...a[0]||(a[0]=[t('<h1 id="_6-como-pagar-tu-compra-paso-a-paso" tabindex="-1">6. Cómo Pagar tu Compra (Paso a Paso) <a class="header-anchor" href="#_6-como-pagar-tu-compra-paso-a-paso" aria-label="Permalink to &quot;6. Cómo Pagar tu Compra (Paso a Paso)&quot;">​</a></h1><p>El proceso de compra en PayMe Panamá es muy sencillo y está dividido en 3 pasos claros para que sepas exactamente qué estás pagando antes de confirmar.</p><hr><h2 id="_6-1-los-3-pasos-del-checkout" tabindex="-1">6.1 Los 3 Pasos del Checkout <a class="header-anchor" href="#_6-1-los-3-pasos-del-checkout" aria-label="Permalink to &quot;6.1 Los 3 Pasos del Checkout&quot;">​</a></h2><p>Para iniciar el pago, pulsa <strong>&quot;Finalizar Compra&quot;</strong> en tu carrito o entra directo a <a href="https://pyme.rsfsecure.site/checkout" target="_blank" rel="noreferrer">https://pyme.rsfsecure.site/checkout</a>:</p><div class="screenshot-box"><div class="screenshot-header"><div class="screenshot-dots"><span class="screenshot-dot red"></span><span class="screenshot-dot yellow"></span><span class="screenshot-dot green"></span></div><span class="screenshot-title">Datos de Envío y Dirección en el Checkout</span><span class="screenshot-url">https://pyme.rsfsecure.site/checkout</span></div><div class="screenshot-body"><img src="'+s+'" alt="Datos de Envío y Dirección en el Checkout" loading="lazy" decoding="async"></div></div><h3 id="paso-1-tus-datos-de-contacto" tabindex="-1">Paso 1: Tus Datos de Contacto <a class="header-anchor" href="#paso-1-tus-datos-de-contacto" aria-label="Permalink to &quot;Paso 1: Tus Datos de Contacto&quot;">​</a></h3><ul><li>Nombre completo, correo electrónico y número de teléfono celular (para que el mensajero te llame al llegar).</li></ul><h3 id="paso-2-direccion-y-metodo-de-envio" tabindex="-1">Paso 2: Dirección y Método de Envío <a class="header-anchor" href="#paso-2-direccion-y-metodo-de-envio" aria-label="Permalink to &quot;Paso 2: Dirección y Método de Envío&quot;">​</a></h3><ul><li>Elige tu <strong>Provincia</strong> (Panamá Centro, Panamá Oeste, Colón, Coclé, Chiriquí, etc.).</li><li>Escribe tu dirección detallada con edificio, casa y punto de referencia.</li><li>Selecciona la opción de envío: verás el costo del flete según tu zona o si tu compra califica para <strong>Envío Gratis</strong>.</li></ul><hr><h2 id="_6-2-paso-3-seleccion-de-metodo-de-pago" tabindex="-1">6.2 Paso 3: Selección de Método de Pago <a class="header-anchor" href="#_6-2-paso-3-seleccion-de-metodo-de-pago" aria-label="Permalink to &quot;6.2 Paso 3: Selección de Método de Pago&quot;">​</a></h2><p>En la pantalla final de pago (<a href="https://pyme.rsfsecure.site/checkout/pago" target="_blank" rel="noreferrer">https://pyme.rsfsecure.site/checkout/pago</a>) eliges cómo deseas abonar tu compra:</p><div class="screenshot-box"><div class="screenshot-header"><div class="screenshot-dots"><span class="screenshot-dot red"></span><span class="screenshot-dot yellow"></span><span class="screenshot-dot green"></span></div><span class="screenshot-title">Opciones de Pago en Panamá</span><span class="screenshot-url">https://pyme.rsfsecure.site/checkout/pago</span></div><div class="screenshot-body"><img src="'+n+'" alt="Opciones de Pago en Panamá" loading="lazy" decoding="async"></div></div><h3 id="¿como-pagar-con-cada-metodo" tabindex="-1">¿Cómo pagar con cada método? <a class="header-anchor" href="#¿como-pagar-con-cada-metodo" aria-label="Permalink to &quot;¿Cómo pagar con cada método?&quot;">​</a></h3><h3 id="_1-pago-con-yappy-banco-general" tabindex="-1">1. Pago con Yappy (Banco General) <a class="header-anchor" href="#_1-pago-con-yappy-banco-general" aria-label="Permalink to &quot;1. Pago con Yappy (Banco General)&quot;">​</a></h3><ul><li>Selecciona la opción <strong>Yappy</strong>.</li><li>Si estás en tu celular, pulsa el botón de Yappy para que se abra automáticamente tu app de Banco General.</li><li>Si estás en la computadora, escanea el código QR en pantalla con la cámara de tu celular desde la app de Banco General o escribe tu número celular.</li><li>Confirma el pago en tu banco y ¡listo! La tienda confirmará tu pedido de inmediato.</li></ul><h3 id="_2-tarjeta-de-credito-o-debito-visa-mastercard-clave" tabindex="-1">2. Tarjeta de Crédito o Débito (Visa, Mastercard, Clave) <a class="header-anchor" href="#_2-tarjeta-de-credito-o-debito-visa-mastercard-clave" aria-label="Permalink to &quot;2. Tarjeta de Crédito o Débito (Visa, Mastercard, Clave)&quot;">​</a></h3><ul><li>Ingresa el número de tu tarjeta, fecha de vencimiento y código de seguridad (CVV de 3 dígitos al reverso).</li><li>El pago se procesa bajo conexión segura y encriptada con tecnología 3D Secure para protección contra fraudes.</li></ul><h3 id="_3-transferencia-bancaria-ach-deposito" tabindex="-1">3. Transferencia Bancaria (ACH / Depósito) <a class="header-anchor" href="#_3-transferencia-bancaria-ach-deposito" aria-label="Permalink to &quot;3. Transferencia Bancaria (ACH / Depósito)&quot;">​</a></h3><ul><li>Verás en pantalla los números de cuenta bancaria oficial de la empresa (Banco General, Banistmo y BAC Panamá).</li><li>Entra a tu banca en línea y realiza la transferencia por el monto exacto de tu compra.</li><li>Toma una captura de pantalla del comprobante de transferencia y súbela en la misma página usando el botón <strong>&quot;Adjuntar Comprobante&quot;</strong>.</li><li>Nuestro equipo validará el ingreso y activará el despacho de tu paquete.</li></ul><hr><h2 id="_6-3-solucion-a-problemas-frecuentes-al-momento-de-pagar" tabindex="-1">6.3 Solución a Problemas Frecuentes al Momento de Pagar <a class="header-anchor" href="#_6-3-solucion-a-problemas-frecuentes-al-momento-de-pagar" aria-label="Permalink to &quot;6.3 Solución a Problemas Frecuentes al Momento de Pagar&quot;">​</a></h2><p>Si experimentas algún inconveniente durante el pago, revisa estas soluciones directas:</p><h3 id="¿que-hacer-si-tu-tarjeta-de-credito-o-debito-fue-rechazada" tabindex="-1">¿Qué hacer si tu tarjeta de crédito o débito fue rechazada? <a class="header-anchor" href="#¿que-hacer-si-tu-tarjeta-de-credito-o-debito-fue-rechazada" aria-label="Permalink to &quot;¿Qué hacer si tu tarjeta de crédito o débito fue rechazada?&quot;">​</a></h3><ol><li><strong>Compras por internet inactivas:</strong> Muchos bancos de Panamá (Banco General, Banistmo, BAC, Caja de Ahorros) requieren habilitar las compras en línea desde su app de banca móvil. Entra a los ajustes de tu tarjeta y asegúrate de que <em>&quot;Compras por Internet&quot;</em> esté encendido.</li><li><strong>Límite diario de compras:</strong> Verifica que el monto de la compra no sobrepase el tope de gasto diario asignado a tu tarjeta.</li><li><strong>Fondos o saldo disponible:</strong> Asegúrate de contar con el saldo suficiente incluyendo el costo de envío y el 7% de ITBMS.</li><li><strong>Datos ingresados incorrectos:</strong> Revisa con atención la fecha de vencimiento y los 3 dígitos del CVV.</li></ol><h3 id="¿que-hacer-si-pagaste-por-yappy-pero-la-pagina-no-avanzo" tabindex="-1">¿Qué hacer si pagaste por Yappy pero la página no avanzó? <a class="header-anchor" href="#¿que-hacer-si-pagaste-por-yappy-pero-la-pagina-no-avanzo" aria-label="Permalink to &quot;¿Qué hacer si pagaste por Yappy pero la página no avanzó?&quot;">​</a></h3><p>En ocasiones, la conexión bancaria puede demorar unos segundos en notificar a la tienda:</p><ul><li>No vuelvas a pagar.</li><li>Guarda la captura de pantalla de la confirmación que emite la app de Banco General.</li><li>Escribe a nuestro WhatsApp oficial indicando tu número de pedido y adjunta la captura. Nuestro personal confirmará la orden manualmente en menos de 5 minutos.</li></ul><h3 id="¿que-hacer-si-hiciste-una-transferencia-ach-y-cerraste-la-ventana-por-error" tabindex="-1">¿Qué hacer si hiciste una transferencia ACH y cerraste la ventana por error? <a class="header-anchor" href="#¿que-hacer-si-hiciste-una-transferencia-ach-y-cerraste-la-ventana-por-error" aria-label="Permalink to &quot;¿Qué hacer si hiciste una transferencia ACH y cerraste la ventana por error?&quot;">​</a></h3><p>Si ya transferiste desde tu banco pero no alcanzaste a adjuntar el recibo:</p><ol><li>Entra a <strong>&quot;Mis Pedidos&quot;</strong> (<a href="https://pyme.rsfsecure.site/cliente/pedidos" target="_blank" rel="noreferrer">https://pyme.rsfsecure.site/cliente/pedidos</a>).</li><li>Localiza la compra que figura en estado <strong>&quot;Pendiente de Pago&quot;</strong>.</li><li>Haz clic en <strong>&quot;Adjuntar Comprobante&quot;</strong> y sube la imagen desde tu galería o computadora.</li><li>También puedes enviárnoslo por correo o WhatsApp con tu número de orden.</li></ol><hr><h2 id="_6-4-preguntas-frecuentes-sobre-metodos-de-pago" tabindex="-1">6.4 Preguntas Frecuentes sobre Métodos de Pago <a class="header-anchor" href="#_6-4-preguntas-frecuentes-sobre-metodos-de-pago" aria-label="Permalink to &quot;6.4 Preguntas Frecuentes sobre Métodos de Pago&quot;">​</a></h2><details class="details custom-block"><summary>¿Puedo pagar contra entrega en efectivo al recibir el paquete?</summary><p>Por políticas de seguridad de nuestros mensajeros y transportistas, todos los pedidos deben pagarse previamente a través de la plataforma (Yappy, tarjetas o transferencia ACH).</p></details><details class="details custom-block"><summary>¿Aceptan tarjetas Clave de bancos de Panamá?</summary><p>Sí, puedes utilizar tus tarjetas de débito con el logo del sistema Clave de cualquier banco de Panamá siempre que cuenten con numeración de 16 dígitos y código de seguridad para transacciones de comercio electrónico.</p></details>',36)])])}const b=e(i,[["render",c]]);export{g as __pageData,b as default};
